// Shape only. No decision is made here on legal grounds: the platform decides
// what matters.
//
// The resolved format runs the message through mailparser, so `from` and `to`
// are objects with a `value` array rather than strings. Reading them as
// strings yields "[object Object]", which is how every forwarded message
// arrived with a sender of "unknown".

const MAX_BYTES = 15 * 1024 * 1024;

// Inline images have no flag by the time n8n hands them over: the resolved
// format keeps content, filename and type and drops mailparser's
// contentDisposition and cid. What is left is the name, and a mail client
// names an inline image for you. A document somebody meant to send has a name
// somebody chose.
const AUTO_NAMED = /^(image|shared image|inline)[-_ ]?\d*\.(png|jpe?g|gif|bmp|webp)$/i;

function addressOf(field) {
  if (!field) return 'unknown';
  const first = field.value?.[0]?.address;
  if (first) return String(first).toLowerCase();
  const text = String(field.text ?? field);
  const angled = text.match(/<([^>]+)>/);
  if (angled) return angled[1].trim().toLowerCase();
  const bare = text.match(/[^\s,;<>]+@[^\s,;<>]+/);
  return bare ? bare[0].toLowerCase() : 'unknown';
}

function everyone(field) {
  const listed = field?.value;
  if (Array.isArray(listed)) {
    return listed
      .filter((one) => one.address)
      .map((one) => ({ name: one.name || null, address: String(one.address).toLowerCase() }));
  }
  return String(field?.text ?? field ?? '')
    .split(',')
    .map((one) => one.trim())
    .filter(Boolean)
    .map((one) => ({
      name: one.replace(/<[^>]+>/, '').trim() || null,
      address: addressOf(one),
    }));
}

const items = $input.all();
const messages = [];

for (let index = 0; index < items.length; index++) {
  const item = items[index];
  const mail = item.json;
  const attachments = [];
  let skippedInline = 0;

  for (const [key, meta] of Object.entries(item.binary ?? {})) {
    const filename = meta.fileName || key;
    if (AUTO_NAMED.test(filename)) {
      skippedInline += 1;
      continue;
    }

    let buffer = null;
    try {
      buffer = await this.helpers.getBinaryDataBuffer(index, key);
    } catch (error) {
      buffer = meta.data ? Buffer.from(meta.data, 'base64') : null;
    }
    if (!buffer || buffer.length === 0 || buffer.length > MAX_BYTES) continue;

    attachments.push({
      filename,
      content_type: meta.mimeType || 'application/octet-stream',
      content_base64: buffer.toString('base64'),
    });
  }

  const body = mail.textPlain || mail.text || mail.textHtml || mail.html || '';

  messages.push({
    external_id: mail.messageId || `${mail.date}-${addressOf(mail.from)}-${mail.subject}`,
    mailbox: $env.LEGAL_MAILBOX,
    sender: addressOf(mail.from),
    subject: mail.subject || '(no subject)',
    body: skippedInline
      ? `${body}\n\n[${skippedInline} inline image(s) from the signature were not stored.]`
      : body,
    received_at: new Date(mail.date).toISOString(),
    participants: everyone(mail.to),
    attachments,
  });
}

return [{ json: { messages } }];

// The signature is over the exact bytes that will be sent, which is why the
// body is serialised here and handed on as a string. Serialising it again in
// the HTTP node would produce a different body and a signature that does not
// verify.
const crypto = require('crypto');
const body = JSON.stringify($json);
const signature = crypto
  .createHmac('sha256', $env.DSNLAI_WEBHOOK_SECRET)
  .update(body)
  .digest('hex');
return [{ json: { body, signature } }];
